.range-wrap{margin-top:11px}
.range-labels{display:flex;justify-content:space-between;font-size:9px;color:#7c899b;margin-bottom:5px}
.range-track{position:relative;height:8px;background:#e4eaf1;border-radius:999px;overflow:hidden}
.range-fill{height:100%;background:#9eb6d1;border-radius:999px}
.range-note{margin-top:5px;font-size:10px;color:#6f7d91;line-height:1.45}

.completeness-track{height:8px;background:#e4eaf1;border-radius:999px;overflow:hidden;margin-top:7px}
.completeness-fill{height:100%;background:#9eb6d1;border-radius:999px}
.panel-note{font-size:10px;color:#6f7d91;line-height:1.5;margin-top:9px}
.health-a{background:#e8f5ee;color:#1c6b40}
.health-b{background:#fff5d9;color:#7d6413}
.health-c{background:#fff1f1;color:#a02b2b}
.health-na{background:#edf1f6;color:#5e6d82}

.stage-sell{background:#fff0e8;color:#9b4c15}
.stage-buy{background:#e9f1fb;color:#24588c}
.stage-phase{background:#f5eefd;color:#68408a}
.alignment-row{display:flex;flex-wrap:wrap;gap:5px;margin-top:9px}
.alignment-chip{font-size:9px;padding:4px 7px;border-radius:999px;background:#eef3f8;color:#50627a}

.notice-card{font-size:12px;line-height:1.5}
.notice-list{margin:0;padding-left:18px}
.notice-list li+li{margin-top:6px}
.notice-warning{color:#7d6413}
.notice-error{color:#a02b2b}
.hidden{display:none}

footer{margin-top:24px;text-align:center;color:#7b8798;font-size:11px}
.footer-sub{font-size:9px}

@media(max-width:600px){
  .status-grid{grid-template-columns:1fr}
  .cards{grid-template-columns:1fr}
